using BARANG.Core.Application.Customers;
using BARANG.Core.Application.Pagination;
using BARANG.Core.Domain.Customers;
using Microsoft.EntityFrameworkCore;

namespace BARANG.Core.Infrastructure.Persistence;

public sealed class CustomerStore(CoreDbContext db):ICustomerStore
{
    public void Add(Customer value)=>db.Customers.Add(value);public void Add(CustomerContact value)=>db.CustomerContacts.Add(value);public void Add(CustomerAddress value)=>db.CustomerAddresses.Add(value);
    public Task<Customer?>FindAsync(Guid id,CancellationToken ct)=>db.Customers.SingleOrDefaultAsync(x=>x.Id==id,ct);public Task<Customer?>FindByCodeAsync(string code,CancellationToken ct)=>db.Customers.SingleOrDefaultAsync(x=>x.CustomerCode==code,ct);public Task<bool>CodeExistsAsync(string code,CancellationToken ct)=>db.Customers.AnyAsync(x=>x.CustomerCode==code,ct);
    public Task<bool>IdentifierExistsAsync(string? national,string? registration,Guid? excludingId,CancellationToken ct)=>db.Customers.AnyAsync(x=>(excludingId==null||x.Id!=excludingId)&&((national!=null&&x.NationalId==national)||(registration!=null&&x.RegistrationNo==registration)),ct);
    public async Task<PagedResult<Customer>>SearchAsync(CustomerQuery query,CancellationToken ct){PagedRequest page=new(query.PageNumber,query.PageSize);IQueryable<Customer> q=db.Customers.AsNoTracking().Where(x=>!query.ActiveOnly||x.IsActive);string search=query.Search?.Trim()??"";if(search.Length>0){string pattern=$"%{search.Replace("%","\\%").Replace("_","\\_")}%";q=q.Where(x=>EF.Functions.ILike(x.CustomerCode,pattern,"\\")||EF.Functions.ILike(x.DisplayName,pattern,"\\")||(x.FirstName!=null&&EF.Functions.ILike(x.FirstName,pattern,"\\"))||(x.LastName!=null&&EF.Functions.ILike(x.LastName,pattern,"\\"))||(x.LegalName!=null&&EF.Functions.ILike(x.LegalName,pattern,"\\"))||(x.PrimaryMobile!=null&&EF.Functions.ILike(x.PrimaryMobile,pattern,"\\"))||(x.PrimaryEmail!=null&&EF.Functions.ILike(x.PrimaryEmail,pattern,"\\"))||(x.NationalId!=null&&EF.Functions.ILike(x.NationalId,pattern,"\\"))||(x.RegistrationNo!=null&&EF.Functions.ILike(x.RegistrationNo,pattern,"\\")));}long total=await q.LongCountAsync(ct);int skip=(page.PageNumber-1)*page.PageSize;List<Customer> items=await q.OrderBy(x=>x.CustomerCode).ThenBy(x=>x.Id).Skip(skip).Take(page.PageSize).ToListAsync(ct);return new(items,page.PageNumber,page.PageSize,total);}
    public async Task<IReadOnlyList<Customer>>OptionsAsync(string? search,bool activeOnly,int limit,CancellationToken ct){IQueryable<Customer>q=db.Customers.AsNoTracking().Where(x=>!activeOnly||x.IsActive);string value=search?.Trim()??"";if(value.Length>0){string pattern=$"%{value.Replace("%","\\%").Replace("_","\\_")}%";q=q.Where(x=>EF.Functions.ILike(x.CustomerCode,pattern,"\\")||EF.Functions.ILike(x.DisplayName,pattern,"\\"));}return await q.OrderBy(x=>x.DisplayName).ThenBy(x=>x.CustomerCode).ThenBy(x=>x.Id).Take(limit).ToListAsync(ct);}
    public Task<CustomerContact?>FindContactAsync(Guid customerId,Guid id,CancellationToken ct)=>db.CustomerContacts.SingleOrDefaultAsync(x=>x.CustomerId==customerId&&x.Id==id,ct);public async Task<IReadOnlyList<CustomerContact>>ListContactsAsync(Guid customerId,bool activeOnly,CancellationToken ct)=>await db.CustomerContacts.AsNoTracking().Where(x=>x.CustomerId==customerId&&(!activeOnly||x.IsActive)).OrderByDescending(x=>x.IsPrimary).ThenBy(x=>x.DisplayOrder).ThenBy(x=>x.Id).ToListAsync(ct);public Task<bool>OtherPrimaryContactExistsAsync(Guid customerId,Guid? excludingId,CancellationToken ct)=>db.CustomerContacts.AnyAsync(x=>x.CustomerId==customerId&&x.IsActive&&x.IsPrimary&&(excludingId==null||x.Id!=excludingId),ct);
    public Task<CustomerAddress?>FindAddressAsync(Guid customerId,Guid id,CancellationToken ct)=>db.CustomerAddresses.SingleOrDefaultAsync(x=>x.CustomerId==customerId&&x.Id==id,ct);public async Task<IReadOnlyList<CustomerAddress>>ListAddressesAsync(Guid customerId,bool activeOnly,CancellationToken ct)=>await db.CustomerAddresses.AsNoTracking().Where(x=>x.CustomerId==customerId&&(!activeOnly||x.IsActive)).OrderByDescending(x=>x.IsPrimary).ThenBy(x=>x.DisplayOrder).ThenBy(x=>x.Id).ToListAsync(ct);public Task<bool>OtherPrimaryAddressExistsAsync(Guid customerId,Guid? excludingId,CancellationToken ct)=>db.CustomerAddresses.AnyAsync(x=>x.CustomerId==customerId&&x.IsActive&&x.IsPrimary&&(excludingId==null||x.Id!=excludingId),ct);
}
